using System.Net;
using System.Text;

namespace PaymentAuthorization.IntegrationTest.PaymentGateway;

/// <summary>
/// A tiny in-process HTTP server that stands in for the real payment provider.
/// Tests configure the response it should return, then inspect the request it
/// actually received, so the wire contract (JSON shapes, status codes) is
/// exercised for real rather than assumed.
/// </summary>
public sealed class FakePaymentProvider : IDisposable
{
    private readonly HttpListener listener = new();
    private readonly CancellationTokenSource cts = new();
    private readonly Task listenLoop;

    public string? ReceivedBody { get; private set; }
    public string? ReceivedPath { get; private set; }
    public string? ReceivedMethod { get; private set; }

    private int responseStatusCode = 200;
    private string responseBody = "{}";

    public FakePaymentProvider()
    {
        var port = GetFreePort();
        BaseAddress = $"http://127.0.0.1:{port}/";
        listener.Prefixes.Add(BaseAddress);
        listener.Start();
        listenLoop = Task.Run(AcceptLoop);
    }

    public string BaseAddress { get; }

    public void RespondWith(int statusCode, string jsonBody)
    {
        responseStatusCode = statusCode;
        responseBody = jsonBody;
    }

    private async Task AcceptLoop()
    {
        while (!cts.IsCancellationRequested)
        {
            HttpListenerContext context;
            try
            {
                context = await listener.GetContextAsync().WaitAsync(cts.Token);
            }
            catch (Exception) when (cts.IsCancellationRequested)
            {
                return;
            }

            using var reader = new StreamReader(context.Request.InputStream, Encoding.UTF8);
            ReceivedBody = await reader.ReadToEndAsync();
            ReceivedPath = context.Request.Url?.AbsolutePath;
            ReceivedMethod = context.Request.HttpMethod;

            var bytes = Encoding.UTF8.GetBytes(responseBody);
            context.Response.StatusCode = responseStatusCode;
            context.Response.ContentType = "application/json";
            context.Response.ContentLength64 = bytes.Length;
            await context.Response.OutputStream.WriteAsync(bytes);
            context.Response.Close();
        }
    }

    private static int GetFreePort()
    {
        var listener = new System.Net.Sockets.TcpListener(IPAddress.Loopback, 0);
        listener.Start();
        var port = ((IPEndPoint)listener.LocalEndpoint).Port;
        listener.Stop();
        return port;
    }

    public void Dispose()
    {
        cts.Cancel();
        listener.Stop();
        listener.Close();
        cts.Dispose();
    }
}

