    public async Task Sends_the_reference_amount_and_currency_as_the_provider_expects()
    {
        provider.RespondWith(200, """{"status":"approved"}""");

        await sut.AuthorizeAsync("ORD-7", new Money(12.5m, "eur"), CancellationToken.None);

        Assert.Equal("POST", provider.ReceivedMethod);
        Assert.Equal("/v1/authorizations", provider.ReceivedPath);
        using var sentBody = JsonDocument.Parse(provider.ReceivedBody!);
        var root = sentBody.RootElement;
        Assert.Equal("ORD-7", root.GetProperty("reference").GetString());
        Assert.Equal(12.5m, root.GetProperty("amount").GetDecimal());
        Assert.Equal("EUR", root.GetProperty("currency").GetString());
    }

    [Fact]
    public async Task An_approved_response_is_read_back_as_Approved()
    {
        provider.RespondWith(200, """{"status":"approved"}""");

        var outcome = await sut.AuthorizeAsync("ORD-7", new Money(10m, "USD"), CancellationToken.None);

        Assert.Equal(AuthorizationOutcome.Approved, outcome);
    }

    [Fact]
    public async Task A_declined_response_is_read_back_as_Declined()
    {
        provider.RespondWith(200, """{"status":"declined"}""");

        var outcome = await sut.AuthorizeAsync("ORD-7", new Money(10m, "USD"), CancellationToken.None);

        Assert.Equal(AuthorizationOutcome.Declined, outcome);
    }

    [Fact]
    public async Task A_402_response_is_read_back_as_Declined_without_reading_the_body()
    {
        provider.RespondWith(402, """{"error":"insufficient_funds"}""");

        var outcome = await sut.AuthorizeAsync("ORD-7", new Money(10m, "USD"), CancellationToken.None);

        Assert.Equal(AuthorizationOutcome.Declined, outcome);
    }

    [Fact]
    public async Task An_unexpected_server_error_surfaces_as_a_failure_instead_of_being_silently_declined()
    {
        provider.RespondWith(500, """{"error":"boom"}""");

        await Assert.ThrowsAsync<HttpRequestException>(
            () => sut.AuthorizeAsync("ORD-7", new Money(10m, "USD"), CancellationToken.None));
    }

    public void Dispose()
    {
        client.Dispose();
        provider.Dispose();
    }
}
